INSERT INTO Benefit VALUES('rewards','Earn 5x points on flights booked directly with airlines or through American Express Travel (up to $500,000 in these purchases per calendar year) and 5x points on prepaid hotels booked through American Express Travel. All other purchases earn 1x points.',NULL,'1393fa8e-5c8f-408c-afc3-809cf439251e','4e2c506f-0825-46b6-8239-4acab255c472',NULL,'5x on flights (direct or Amex Travel, up to $500k/yr) and prepaid Amex Travel hotels; 1x on everything else.','["points","earning","5x flights","5x hotels","amex travel"]','Earning rates','5x travel / 1x other',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('car_rental','The Platinum Card includes complimentary elite status with several rental car programs: Hertz Gold Plus Rewards President''s Circle, Avis Preferred Plus, and National Emerald Club Executive. These give you faster pick-up (skip the counter), a wider choice of vehicles, and potential upgrades.','Enroll each program once via the Amex benefits portal, then add your membership number to your rental profile. Status is valid while you hold the card.','927fd798-70ce-443e-8704-0c7d15a14ce1','4e2c506f-0825-46b6-8239-4acab255c472',NULL,'Complimentary elite status with Hertz (President''s Circle), Avis (Preferred Plus), and National (Emerald Club Executive).','["rental car","hertz","avis","national","elite status","upgrade","skip the line"]','Rental car elite status (Hertz, Avis, National)',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('car_rental','Amex provides Car Rental Loss and Damage Insurance when you charge the entire rental to the card and decline the rental company''s collision damage waiver. Within the U.S. it is secondary to your personal auto insurance; outside the U.S. it is primary. Coverage is for damage/theft of the rental vehicle, not liability.','Pay for the rental with the Platinum Card and decline the rental company''s CDW/LDW. Coverage is automatic; file a claim through Amex if damage occurs.','86bd8fd5-8db8-4430-a382-452248640d51','4e2c506f-0825-46b6-8239-4acab255c472','https://www.americanexpress.com/en-us/benefits/insurance/car-rental-insurance/','Automatic rental car loss and damage coverage when you pay with the card and decline the rental company''s insurance.','["rental car","insurance","collision","damage waiver","primary","secondary"]','Car Rental Loss and Damage Insurance','Secondary in the U.S., primary abroad',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','Book through Amex Travel''s Fine Hotels + Resorts or The Hotel Collection to get a $200 annual statement credit on prepaid FHR/The Hotel Collection stays, plus room upgrades when available, daily breakfast for two, and guaranteed 4pm late checkout at FHR properties.','Book a prepaid stay at a Fine Hotels + Resorts or The Hotel Collection property through Amex Travel.','ec4d3c13-92f4-4db7-b168-9ab671894352','4e2c506f-0825-46b6-8239-4acab255c472',NULL,'$200 annual credit on prepaid Fine Hotels + Resorts or The Hotel Collection bookings, plus perks like upgrades and late checkout.','["hotel","travel","fine hotels","upgrade","breakfast","credit"]','Fine Hotels + Resorts / Hotel Collection credit','$200/year',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','$200 in airline fee credits each calendar year for incidental fees (checked bags, seat assignments, in-flight food/drinks) on your selected qualifying airline. Airfare itself does not qualify.','Choose one qualifying airline in your Amex account, then pay incidentals with the card.','7053e44d-fcdf-4d0f-bab0-dfb6456f656c','4e2c506f-0825-46b6-8239-4acab255c472',NULL,'$200 annual credit toward incidental airline fees on one selected airline.','["airline","checked bag","incidentals","travel","credit"]','Airline fee credit','$200/year',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','$15 in Uber Cash each month, plus a $35 bonus in December, for rides and Uber Eats in the U.S. Add the Platinum Card as a payment method in the Uber app to receive it.','Add the card as the payment method in the Uber app; the credit loads automatically each month.','d86b9317-9b42-4ddb-8fef-da9626bd9d81','4e2c506f-0825-46b6-8239-4acab255c472',NULL,'$15/month Uber Cash plus a $35 December bonus.','["uber","rideshare","uber eats","credit","monthly"]','Uber Cash','$200/year total',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('lounge','Access to the Global Lounge Collection, including Centurion Lounges, Priority Pass Select, Delta Sky Club (when flying Delta), and International American Express Lounges. Enrollment may be required for some programs.','Enroll in Priority Pass Select through Amex, then show your card and boarding pass at eligible lounges.','a47d0f5b-2c2a-47c7-bd76-89a65468135b','4e2c506f-0825-46b6-8239-4acab255c472',NULL,'Global Lounge Collection access, including Centurion Lounges and Priority Pass Select.','["lounge","airport","priority pass","centurion","travel"]','Airport lounge access',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('security','Up to $100 statement credit every 4 years for Global Entry, or up to $85 for TSA PreCheck, when you pay the application fee with the card.',NULL,'4766234e-03eb-453a-8371-4f2b3e5158f0','4e2c506f-0825-46b6-8239-4acab255c472',NULL,'Statement credit for Global Entry or TSA PreCheck application fees.','["global entry","tsa precheck","security","airport","credit"]','Global Entry / TSA PreCheck credit','Up to $100 every 4 years',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','Up to $199 annual statement credit for a CLEAR Plus membership, which lets you verify your identity with your eyes or fingerprint to skip security lines at airports and stadiums.',NULL,'a1794061-ef22-4313-8e14-81a3c181d48d','4e2c506f-0825-46b6-8239-4acab255c472',NULL,'Annual statement credit for a CLEAR Plus membership.','["clear","security","airport","biometric","credit"]','CLEAR Plus credit','Up to $199/year',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('shopping','New purchases are covered against accidental damage or theft for 90 days, up to $10,000 per occurrence and $50,000 per year. A phone bought with the card is covered if it is stolen or damaged soon after purchase.','Pay for the item with the card, then file a claim through Amex within 90 days if it is damaged or stolen.','72d7d3a0-1875-4c93-8316-5292b0e0e3c0','4e2c506f-0825-46b6-8239-4acab255c472',NULL,'New purchases, including a phone, are covered against theft or damage for 90 days.','["purchase protection","phone","theft","damage","new purchase","shopping","dropped","broken"]','Purchase Protection','Up to $10,000 per claim',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('shopping','Eligible items get up to one extra year added to the manufacturer''s warranty when the full purchase is made with the card, on warranties of five years or less.',NULL,'8ac4260e-fc0d-4690-9839-a665bb43793a','4e2c506f-0825-46b6-8239-4acab255c472',NULL,'Adds up to one extra year to the manufacturer''s warranty on eligible purchases.','["extended warranty","warranty","phone","electronics","repair"]','Extended Warranty','Up to 1 extra year',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','Pay your monthly cell phone bill with the card and get up to $800 per claim ($1,600 per year, $50 deductible) if your phone is damaged or stolen.','Set the card as the payment method for your monthly wireless bill to activate coverage.','ba684417-b584-41c6-98b3-1a24166582a4','4e2c506f-0825-46b6-8239-4acab255c472',NULL,'Covers a damaged or stolen phone (up to $800 per claim) when you pay your monthly cell bill with the card.','["cell phone protection","phone","cracked screen","theft","cell bill","dropped","broken","damaged"]','Cell Phone Protection','Up to $800 per claim',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('rewards','Earn 8x points on purchases through Chase Travel (including The Edit) and 4x points on flights and hotels booked directly with the airline or hotel. Earn 3x points on dining worldwide and 1x on all other purchases.',NULL,'f1262c7c-3b31-4cd9-8cc0-3bdc48c6d44f','59b8e769-16f4-4cf6-b9ac-36a989727f7c',NULL,'8x Chase Travel, 4x direct flights/hotels, 3x dining, 1x other.','["points","earning","8x chase travel","4x flights","3x dining"]','Earning rates','8x Chase Travel',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('car_rental','Auto Rental Collision Damage Waiver is primary coverage (it pays before your personal auto insurance) for damage or theft of a rental vehicle when you charge the rental to the card and decline the rental company''s collision damage waiver. Coverage is up to the actual cash value of the vehicle, generally up to $75,000, and applies in the U.S. and abroad. It does not cover liability.','Charge the full rental to the card and decline the rental company''s CDW/LDW. Coverage is automatic.','6935a679-9d48-4b11-a119-fcaee3a3f18c','59b8e769-16f4-4cf6-b9ac-36a989727f7c','https://www.chase.com/personal/credit-cards/education/benefits/sapphire-reserve-auto-rental-collision-damage-waiver','Primary rental car collision damage waiver up to $75,000 when you pay with the card and decline the rental company''s insurance.','["rental car","insurance","primary","collision","damage waiver","car rental"]','Primary Auto Rental Collision Damage Waiver','Up to $75,000',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','Earn a $300 annual statement credit for travel purchases, automatically applied to purchases coded as travel (airfare, hotels, rental cars, transit, etc.).','Automatic — just use the card for travel purchases.','1aac18c2-f0b3-42e5-b608-6ae76c6c98f5','59b8e769-16f4-4cf6-b9ac-36a989727f7c',NULL,'$300 annual statement credit that automatically applies to travel purchases.','["travel","credit","airfare","hotel","rental car"]','$300 annual travel credit','$300/year',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('lounge','Priority Pass Select membership with access to 1,300+ airport lounges worldwide, plus access to Chase Sapphire Lounges by The Club and select restaurants via the Priority Pass network.','Activate Priority Pass through the Chase benefits portal, then present your Priority Pass card or digital pass.','841406f2-cba3-4775-a405-c2359ccd985a','59b8e769-16f4-4cf6-b9ac-36a989727f7c',NULL,'Priority Pass Select plus access to Chase Sapphire Lounges.','["lounge","priority pass","airport","travel"]','Airport lounge access',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('insurance','Trip cancellation/interruption coverage up to $10,000 per person and $20,000 per trip when you pay for the trip with the card. Also includes baggage delay, lost luggage, and trip delay reimbursement.',NULL,'c01c62f3-f0c1-4dd3-82f2-9529f8a40a8d','59b8e769-16f4-4cf6-b9ac-36a989727f7c',NULL,'Trip cancellation/interruption up to $10,000 per person, plus baggage and trip delay coverage.','["trip cancellation","trip delay","baggage","insurance","travel"]','Trip protection','Up to $10,000 per person',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('dining','Complimentary DoorDash DashPass membership (activate by a set date) and monthly DoorDash credits for eligible purchases, plus other rotating dining offers.',NULL,'5c2d16f8-19ed-4759-91a0-9a4a13312388','59b8e769-16f4-4cf6-b9ac-36a989727f7c',NULL,'Complimentary DashPass membership and monthly DoorDash credits.','["doordash","dashpass","dining","delivery","credit"]','DoorDash DashPass and credits',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('security','Up to $100 statement credit every 4 years for Global Entry, or up to $85 for TSA PreCheck, when you pay the application fee with the card.',NULL,'e1c3fb66-8e5d-4a01-9bcd-5672772f3268','59b8e769-16f4-4cf6-b9ac-36a989727f7c',NULL,'Global Entry or TSA PreCheck application fee credit.','["global entry","tsa precheck","security","credit"]','Global Entry / TSA PreCheck credit','Up to $100 every 4 years',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('shopping','New purchases are covered against damage or theft for 120 days, up to $10,000 per claim and $50,000 per account. A phone bought with the card is covered if it is damaged or stolen soon after purchase.','Pay for the item with the card, then file a claim through Chase within 120 days if it is damaged or stolen.','81b73c5d-25be-446b-9253-e1c5c767e73b','59b8e769-16f4-4cf6-b9ac-36a989727f7c',NULL,'New purchases, including a phone, are covered against damage or theft for 120 days.','["purchase protection","phone","theft","damage","new purchase","shopping","dropped","broken"]','Purchase Protection','Up to $10,000 per claim',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('shopping','Extends the manufacturer''s warranty by up to one additional year on eligible purchases with warranties of three years or less.',NULL,'9aac44d1-20c8-4217-96f9-36a44b3bd0bc','59b8e769-16f4-4cf6-b9ac-36a989727f7c',NULL,'Adds up to one extra year to the manufacturer''s warranty on eligible purchases.','["extended warranty","warranty","phone","electronics","repair"]','Extended Warranty','Up to 1 extra year',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','Pay your monthly cell phone bill with the card and get up to $1,000 per claim ($1,500 per year, $50 deductible) if your phone is damaged or stolen.','Set the card as the payment method for your monthly wireless bill to activate coverage.','e341c913-4154-41ef-ba5e-02fc36051d87','59b8e769-16f4-4cf6-b9ac-36a989727f7c',NULL,'Covers a damaged or stolen phone (up to $1,000 per claim) when you pay your monthly cell bill with the card.','["cell phone protection","phone","cracked screen","theft","cell bill","dropped","broken","damaged"]','Cell Phone Protection','Up to $1,000 per claim',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('rewards','Earn 10x miles on hotels and rental cars booked through Capital One Travel, 5x miles on flights and vacation rentals booked through Capital One Travel, and an unlimited 2x miles on all other purchases.',NULL,'2a98ff7e-5f7f-4786-b8ec-5820af004483','4d353cc3-f842-41db-ad53-1a242f9180c4',NULL,'10x hotels/rental cars and 5x flights via Capital One Travel; 2x on everything else.','["miles","earning","10x hotels","5x flights","2x everything"]','Earning rates','2x everything / 10x travel',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('car_rental','Primary rental car insurance for damage or theft of a rental vehicle when you charge the rental to the card and decline the rental company''s collision damage waiver. Applies to most rental cars worldwide; excludes exotic/expensive vehicles.','Pay with the card and decline the rental company''s CDW/LDW.','3d9ad868-f379-416f-b4f2-3f1dda0bcd01','4d353cc3-f842-41db-ad53-1a242f9180c4',NULL,'Primary rental car collision damage coverage when you pay with the card and decline the rental company''s insurance.','["rental car","insurance","primary","collision","damage waiver"]','Primary rental car insurance',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
