INSERT INTO Benefit VALUES('travel','Receive 10,000 bonus miles every account anniversary, which can be worth roughly $100+ toward travel.',NULL,'bcf4fa62-fdf8-4d65-8208-d53542822f52','4d353cc3-f842-41db-ad53-1a242f9180c4',NULL,'10,000 bonus miles every account anniversary.','["miles","anniversary","rewards","travel"]','Anniversary bonus miles',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','Pay your monthly cell phone bill with the card and get up to $800 per claim ($1,000 per year, $50 deductible) if your phone is damaged or stolen.','Set the card as the payment method for your monthly wireless bill to activate coverage.','362d94c8-6ca3-44f5-b890-9e71e0eb7afe','4d353cc3-f842-41db-ad53-1a242f9180c4',NULL,'Covers a damaged or stolen phone (up to $800 per claim) when you pay your monthly cell bill with the card.','["cell phone protection","phone","cracked screen","theft","cell bill","dropped","broken","damaged"]','Cell Phone Protection','Up to $800 per claim',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('security','Use your eyes or fingerprint to verify your identity at CLEAR pods and skip the document-check portion of the security line at 55+ U.S. airports and many stadiums and venues. You still go through the physical screening checkpoint.','Enroll online or at a CLEAR pod, complete identity verification, then use the CLEAR lane at participating airports.','3f3d02e7-a49f-4ce2-be4a-9c8cedc93e3e','a64e3eab-dc48-4bc5-8e14-23105d6413d4',NULL,'Skip the ID-check line at 55+ airports and select venues using biometric verification.','["airport","security","tsa","biometric","skip the line","travel"]','Skip the security line at airports',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('security','Add family members or travel companions to your CLEAR account (pricing varies; children under 18 are free with an adult member).',NULL,'022250db-a585-4245-a8c3-9a55a9e09ad6','a64e3eab-dc48-4bc5-8e14-23105d6413d4',NULL,'Add family members or travel companions to your account; kids under 18 free with an adult.','["family","add member","airport","security"]','Family members and companions',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('shopping','Executive members earn a 2% annual reward on most Costco and Costco.com purchases (some exclusions), paid as a reward certificate. The reward is capped at $1,250 per year.',NULL,'63881151-797c-4a2a-a00e-059e70368cbf','17eca54e-7114-4a0a-a2a4-44ddbb92b5d1',NULL,'2% annual reward on most Costco purchases, up to $1,250/year.','["reward","cash back","shopping","warehouse","annual"]','2% annual reward','Up to $1,250/year',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('car_rental','Costco Travel offers member-only rental car rates with major agencies (Enterprise, Alamo, National, Budget, Avis, Hertz). Rates often include a free additional driver and there is no booking fee, plus you can stack your credit card''s rental car insurance.','Book through Costco Travel, then pay with a card that offers rental car insurance and decline the rental company''s CDW.','dd03221d-62aa-4ada-bcde-b8d3d23ecd1c','17eca54e-7114-4a0a-a2a4-44ddbb92b5d1',NULL,'Member-only rental car rates with no booking fees and often a free additional driver.','["rental car","costco travel","car rental","discount","additional driver"]','Costco Travel rental car rates',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','Costco Travel packages for hotels, cruises, and vacation rentals often include Costco Shop Cards or extra perks. Executive members also earn the 2% annual reward on eligible travel purchases.',NULL,'50e1fab5-b1e1-4fb7-8665-90110f3d2cb3','17eca54e-7114-4a0a-a2a4-44ddbb92b5d1',NULL,'Member pricing and perks on Costco Travel hotel, cruise, and vacation packages.','["travel","hotel","cruise","vacation","costco travel"]','Costco Travel packages',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','Discounted gasoline at Costco gas stations (typically among the lowest locally) and Costco''s Concierge tech support and extended warranty on many electronics.',NULL,'8c773ac5-31dc-4144-8629-454f1ec3091f','17eca54e-7114-4a0a-a2a4-44ddbb92b5d1',NULL,'Discounted gas plus free tech support and extended warranty on many electronics.','["gas","fuel","electronics","warranty","concierge"]','Gas discounts and Concierge services',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('shopping','Shop the warehouse and Costco.com with member-only pricing on groceries, electronics, appliances, and more. Gold Star covers the member plus a free household card for one other person at the same address.','Show your membership card (or the Costco app) at the door and at checkout.','9b6ef623-959d-4f7b-9fec-de9b85e9223b','c7116b3e-694a-45fb-a7a9-2dce3605bf9a',NULL,'Warehouse and Costco.com access with member-only pricing, plus a free household card.','["warehouse","grocery","member pricing","household card"]','Warehouse access and member pricing',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('car_rental','Costco Travel offers member-only rental car rates with major agencies (Enterprise, Alamo, National, Budget, Avis, Hertz). Rates often include a free additional driver and there is no booking fee, and you can still stack your credit card''s rental car insurance.','Book through Costco Travel, pay with a card that offers rental car insurance, and decline the rental company''s CDW.','54b1f04e-a808-45ba-b7aa-062aa5b57d73','c7116b3e-694a-45fb-a7a9-2dce3605bf9a',NULL,'Member-only rental car rates with no booking fees and often a free additional driver.','["rental car","costco travel","car rental","discount","additional driver"]','Costco Travel rental car rates',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','Discounted gasoline at Costco gas stations, plus member pricing at the pharmacy, optical, and hearing aid centers. Includes Costco Concierge free tech support and extended warranty on many electronics.',NULL,'449a7873-7af4-4f23-864c-e9efaa6b6804','c7116b3e-694a-45fb-a7a9-2dce3605bf9a',NULL,'Discounted gas, pharmacy and optical savings, plus free tech support and extended warranty.','["gas","fuel","pharmacy","optical","warranty","concierge"]','Gas, pharmacy, and Concierge services',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('car_rental','Members get discounts at Hertz, Avis, and other rental agencies, often with no additional-driver fee for a spouse or domestic partner and member-only rates. AAA also offers its own ''Show Your Card & Save'' discounts.','Show your AAA card or use the AAA discount code when booking with a participating rental agency.','c364a5e6-9f11-4e2c-afc1-919971a92523','778bf340-f467-4cc5-800f-5287e9482ac3',NULL,'Member discounts at Hertz, Avis, and other rental agencies, often including a free additional driver.','["rental car","discount","hertz","avis","additional driver","aaa"]','Rental car discounts',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('insurance','Roadside assistance including towing, jump-starts, flat tire changes, lockout service, and fuel delivery. Coverage limits and number of service calls depend on your membership tier (Classic, Plus, Premier).','Call the AAA roadside number or use the app when you need help; the responding provider bills AAA directly.','9cc9f128-e0ad-4d8a-9836-9d44f60f3588','778bf340-f467-4cc5-800f-5287e9482ac3',NULL,'Roadside assistance: towing, jump-starts, tire changes, lockouts, and fuel delivery.','["roadside","towing","jump start","flat tire","lockout","car"]','Roadside assistance',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','AAA members get discounts on hotels, cruises, and attractions, plus access to AAA travel agents and free maps/TripTiks.',NULL,'1de37647-7115-4897-8dad-c0fa6932b754','778bf340-f467-4cc5-800f-5287e9482ac3',NULL,'Discounts on hotels, cruises, and attractions, plus trip planning resources.','["hotel","cruise","discount","travel","tripptik"]','Travel discounts and planning',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('shopping','Plus members get free shipping on most online orders, free curbside pickup, early shopping hours, and 2% Sam''s Cash on qualifying purchases.','Scan your membership at checkout. Sam''s Cash accumulates and can be redeemed in-club or online.','fd7cfb82-a038-4736-b6b5-c01e30d56242','b2f3cf5b-3981-40e1-aabe-2feee40a2234',NULL,'Free shipping, early shopping hours, and 2% Sam''s Cash on qualifying purchases.','["warehouse","free shipping","cash back","early shopping","sams cash"]','Free shipping and Sam''s Cash','2% Sam''s Cash',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','Members save on fuel at Sam''s Club gas stations and get member pricing at the pharmacy and optical centers.',NULL,'e332cd85-aaaf-4fee-894c-0d2e6469f4ad','b2f3cf5b-3981-40e1-aabe-2feee40a2234',NULL,'Discounted fuel plus pharmacy and optical member pricing.','["fuel","gas","pharmacy","optical","discount"]','Fuel and pharmacy savings',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('shopping','Free fast delivery on millions of items, plus access to Prime Video, Prime Music, Prime Reading, and Prime Gaming.','Sign in and look for the Prime badge on eligible items, or open the Prime Video app.','97bc5d99-25dc-490e-9978-6f9338ddffe0','83236f67-efab-409a-bac4-e0f20d326f7f',NULL,'Free fast shipping plus Prime Video, Music, Reading, and Gaming.','["shipping","prime video","prime music","streaming","delivery"]','Free shipping and Prime Video',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('shopping','Prime members get exclusive Whole Foods Market deals and Amazon Fresh grocery discounts, plus savings on prescriptions through Amazon Pharmacy and RxPass.',NULL,'a6d346e4-d41d-413a-a1a8-5b956d98515e','83236f67-efab-409a-bac4-e0f20d326f7f',NULL,'Exclusive Whole Foods and Amazon Fresh deals, plus pharmacy savings.','["whole foods","grocery","amazon fresh","pharmacy","rxpass"]','Grocery and pharmacy savings',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('shopping','Free delivery on orders over $35, reduced service fees, and 5% back on eligible pickup orders. Benefits can be shared with one family account.','Link the membership to your Instacart account and choose Instacart+ at checkout.','41160e23-477b-4722-bd19-4baab23d5509','7803b358-2146-42fa-a625-bbe73875e702',NULL,'Free delivery over $35 and reduced service fees, shareable with family.','["grocery","delivery","free delivery","pickup","instacart"]','Free grocery delivery',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','Redeem points for free nights, and get every fifth consecutive night free on award stays. Members also get member-only rates and free Wi-Fi.','Join for free, then book direct with Marriott and select the member rate.','8075f439-6938-4a8f-9f44-c9e4ef98aca1','d27c7994-3621-4828-b62b-cbb24f39d4d5',NULL,'Fifth night free on award stays, member rates, and free Wi-Fi.','["hotel","free night","fifth night free","points","marriott"]','Fifth night free on award stays',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','Points do not expire with account activity, and reward stays of five or more nights get the fifth night free. Members get member discounts, free Wi-Fi, digital check-in, and room selection.','Join for free, book direct, and choose the member rate; use the app for digital check-in.','c19f365c-6424-44bc-9ad8-bf837b1fb84a','089afdba-51d8-439d-8475-1b71d6405fb1',NULL,'Fifth night free on reward stays, member discounts, and digital check-in.','["hotel","points","fifth night free","digital check-in","hilton"]','Fifth night free on reward stays',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('rewards','Earn 5x points on flights and prepaid hotels booked through American Express Travel (up to $500,000 in these purchases per calendar year) and 1.5x points on eligible purchases of $5,000 or more (up to $2 million per year). Other purchases earn 1x points.',NULL,'8c52313c-1cdd-4773-b47b-2a9e87086cec','33dff776-d101-431e-bbee-4c9e78e9945c',NULL,'5x Amex Travel flights and prepaid hotels (up to $500k/yr), 1.5x on large purchases, 1x other.','["points","earning","5x travel","1.5x","business"]','Earning rates','5x Amex Travel',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','Up to $200 in annual statement credits for U.S. purchases at Dell Technologies after enrollment, useful for monitors, laptops, and accessories.',NULL,'639af51e-49eb-4a3a-9147-f858d5038454','33dff776-d101-431e-bbee-4c9e78e9945c',NULL,'$200 annual Dell Technologies credit for business technology purchases.','["dell","technology","credit","business","hardware","laptop","computer","monitor"]','Dell Technologies credit','$200/year',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','Up to $120 in annual credits for Indeed hiring and up to $150 for Adobe Creative Cloud purchases when you enroll and pay with the card.',NULL,'4fbcb6fd-292e-4823-9bed-b8599875944d','33dff776-d101-431e-bbee-4c9e78e9945c',NULL,'Annual credits toward Indeed hiring and Adobe Creative Cloud.','["indeed","adobe","hiring","software","credit","business"]','Indeed and Adobe credits','Up to $270/year',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','Get 35% of your points back when you use Pay with Points for eligible flights through Amex Travel, plus access to the Global Lounge Collection.',NULL,'6813cb49-8213-4cae-8d58-2aecf63c66b8','33dff776-d101-431e-bbee-4c9e78e9945c',NULL,'35% points rebate on eligible flights booked with points, plus lounge access.','["points","flights","amex travel","lounge","business"]','35% points rebate on flights',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','Includes InMail credits to message people outside your network, applicant insights to see how you compare to other candidates, and access to LinkedIn Learning courses.',NULL,'b11ed682-a8e8-4f7d-9ed1-e85488aed3e2','2d21c4ac-30bb-401f-bc3b-b7a63326f41f',NULL,'InMail credits, applicant insights, and LinkedIn Learning access.','["career","inmail","linkedin learning","networking","jobs"]','Networking and learning tools',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','One membership gives access to thousands of gyms, studios, and wellness apps. Many employers subsidize the plan, and you can check in at different locations.',NULL,'16d1969e-61e0-40d2-bdfc-4e3bb157dd12','51860f53-5dd3-439c-8582-7c57647ac9b9',NULL,'Access to a network of gyms, studios, and wellness apps, often employer-subsidized.','["gym","fitness","wellness","wellhub","gympass","employer"]','Gym and wellness network access',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('security','Stores passwords, passkeys, and payment cards in an encrypted vault, monitors for data breaches, and includes Travel Mode to hide sensitive vaults when crossing borders.',NULL,'31de4144-fd6b-484e-96e4-e52921f89df8','e043b17d-5f17-425c-9408-3c6a6b595fea',NULL,'Encrypted password vault with breach monitoring and Travel Mode.','["password manager","security","breach","passkeys","travel mode"]','Password manager and breach alerts',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('streaming','Ad-free listening, offline downloads, and high-quality audio. Premium also includes a monthly audiobook listening allowance, and some plans bundle Hulu.',NULL,'82321e8d-79cd-4d9f-afc4-0077e2888cf5','41734b5d-44d7-4760-977d-b6a46100f437',NULL,'Ad-free music, offline downloads, and audiobook listening hours.','["music","streaming","audiobooks","offline","ad-free"]','Ad-free music and audiobooks',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('streaming','Watch YouTube without ads, play videos in the background or picture-in-picture, download videos for offline viewing, and get YouTube Music Premium included.',NULL,'f176e4b2-175e-42f3-bcdd-883c2a102f96','0c1866db-eeb5-4d45-ac18-a9289702aa11',NULL,'Ad-free YouTube, background play, downloads, and YouTube Music.','["youtube","streaming","ad-free","youtube music","downloads"]','Ad-free YouTube and YouTube Music',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('rewards','Earn 5x points on purchases through Chase Travel; 3x on dining, on gas stations and EV charging, on vacation homes at top brands, and on top streaming services and online grocery (exclusions apply); 2x on all other travel; and 1x on everything else.',NULL,'cbb0a21f-8b6b-470b-a49a-c4cc0e061467','9e4eb315-52b9-4b81-9117-b27a464cd9de',NULL,'5x Chase Travel, 3x dining/gas/streaming/online grocery, 2x other travel, 1x other.','["points","earning","5x chase travel","3x dining","2x travel"]','Earning rates','5x Chase Travel',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('car_rental','Primary Auto Rental Coverage when you charge the rental to the card and decline the rental company''s collision insurance. Reimburses theft and collision damage up to $60,000 for most vehicles.','Pay for the rental with the card and decline the rental company''s CDW/LDW.','fb74fd11-aa6a-46de-9fef-d84ae8604d23','9e4eb315-52b9-4b81-9117-b27a464cd9de',NULL,'Primary rental car coverage up to $60,000 when you pay with the card and decline the rental company''s insurance.','["rental car","insurance","primary","collision","car rental"]','Primary Auto Rental Coverage','Up to $60,000',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('shopping','Purchase Protection covers eligible new purchases for 120 days against damage or theft, up to $500 per item.',NULL,'ee7c8087-b0a5-493d-9111-dabf7f717959','9e4eb315-52b9-4b81-9117-b27a464cd9de',NULL,'New purchases are covered against damage or theft for 120 days (up to $500 per item).','["purchase protection","phone","theft","damage","shopping"]','Purchase Protection','Up to $500 per item',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','Trip Cancellation and Interruption Insurance reimburses up to $10,000 per covered traveler and $20,000 per trip for prepaid, non-refundable travel if a trip is canceled or cut short. Also includes trip delay and lost luggage coverage.',NULL,'2949bbf5-90f5-4645-9cda-c7b817d59c1a','9e4eb315-52b9-4b81-9117-b27a464cd9de',NULL,'Trip cancellation and interruption up to $10,000 per traveler, plus delay and lost luggage coverage.','["trip cancellation","trip delay","luggage","insurance","travel"]','Trip protection','Up to $10,000 per traveler',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','Up to $100 in annual statement credits for hotel stays booked through Chase Travel, plus a Global Entry, TSA PreCheck, or NEXUS application fee credit of up to $120 every four years.',NULL,'239309fa-91b9-4b71-baba-89cfcfda4887','9e4eb315-52b9-4b81-9117-b27a464cd9de',NULL,'$100 annual Chase Travel hotel credit and up to $120 for Global Entry/TSA PreCheck.','["hotel credit","global entry","tsa precheck","travel"]','Travel credits','$100/year + $120/4 years',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('dining','Complimentary DashPass membership for DoorDash and Caviar (a $120 value for 12 months) plus a $10 monthly promo on eligible non-restaurant orders.',NULL,'79e667b9-9d2d-40ab-b4d1-7dcd3377f5ce','9e4eb315-52b9-4b81-9117-b27a464cd9de',NULL,'Complimentary DoorDash DashPass plus $10/month in DoorDash credits.','["doordash","dashpass","dining","delivery","credit"]','DoorDash DashPass and credits',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
