INSERT INTO Benefit VALUES('rewards','Earn 4x points at restaurants worldwide (up to $50,000 in purchases per calendar year, then 1x) and 4x points at U.S. supermarkets (up to $25,000 per year, then 1x). Earn 3x points on flights booked through American Express Travel and 2x on prepaid car rentals booked through Amex Travel; 1x on everything else.',NULL,'a70307f0-5f3e-4946-9c5b-52b25df663a5','61f05f9e-6bc3-4a56-a2fb-7d9e715feccb',NULL,'4x dining (up to $50k/yr) and U.S. supermarkets (up to $25k/yr); 3x Amex Travel flights; 1x other.','["points","earning","4x dining","4x groceries","3x flights"]','Earning rates','4x dining/groceries',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('dining','Up to $120 in annual dining statement credits at participating partners (such as Grubhub, Cheesecake Factory, and select others) and up to $120 in Uber Cash annually ($10/month).',NULL,'b1fdc8e5-bc76-4515-9a2e-3dfce3c2bdf1','61f05f9e-6bc3-4a56-a2fb-7d9e715feccb',NULL,'$120 annual dining credit plus $120 annual Uber Cash.','["dining credit","uber cash","grubhub","credit","dining"]','Dining and Uber credits','Up to $240/year',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('rewards','Earn 5% cash back on travel purchased through Chase Travel, 3% on dining (including takeout and eligible delivery) and drugstores, and an unlimited 1.5% on all other purchases.',NULL,'cb18b26c-6502-4695-aa29-9fe1a2519fa3','e935affb-c5bc-4f02-9a43-c4db7e486705',NULL,'5% Chase Travel, 3% dining and drugstores, 1.5% everywhere else.','["cash back","earning","5% chase travel","3% dining","1.5% base"]','Earning rates','1.5% base',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('shopping','Includes purchase protection and extended warranty on eligible items, plus trip cancellation and interruption insurance on eligible travel.',NULL,'3508c991-a4d0-48c4-9180-fc7c0d1612d8','e935affb-c5bc-4f02-9a43-c4db7e486705',NULL,'Purchase protection, extended warranty, and trip insurance on eligible purchases.','["purchase protection","warranty","trip insurance","shopping"]','Purchase and travel protections',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
