INSERT INTO Benefit VALUES('dining','$0 delivery fee and reduced service fees on eligible Uber Eats orders over the minimum subtotal, plus up to 10% off eligible delivery and pickup orders.',NULL,'2818243a-a712-417d-b7f8-94181c803f52','78744a1e-6853-4542-9a00-f364ed0a65ed',NULL,'$0 delivery fees and up to 10% off eligible Uber Eats orders.','["uber eats","delivery","dining","food delivery","delivery fee"]','$0 delivery fee on Uber Eats',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
