INSERT INTO Benefit VALUES('everyday','Earn WOWPoints when you shop through Perks at Work (10x points is like getting 10% back) and access free online classes and coaching through the Community Online Academy.',NULL,'0bfc3fc6-4875-429c-b54d-3ab709f20edc','b4db4cbf-698c-482e-9753-b28f2e0a94f0',NULL,'Earn WOWPoints on purchases plus free online classes and coaching.','["wowpoints","rewards","classes","coaching","wellness"]','WOWPoints and free classes',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','Includes Word, Excel, PowerPoint, and Outlook, plus 1 TB of OneDrive cloud storage per person and AI features in supported apps.',NULL,'ee9026a1-226c-4bef-8c9f-2241ddbb0083','72f3f1e9-222c-4f6a-9470-d3e7e40b6e03',NULL,'Office apps plus 1 TB of OneDrive cloud storage and AI features.','["office","onedrive","storage","productivity","work"]','Office apps and 1 TB storage',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('shopping','Free shipping with no order minimum on eligible items, free same-day delivery from your store on orders $35+, and free curbside pickup.',NULL,'457f178a-9384-49cd-abf4-bd6398801c82','01816d90-9ca1-406a-b20e-db47c0287e7e',NULL,'Free shipping with no minimum, plus free same-day delivery on $35+ orders.','["shipping","delivery","grocery","walmart","free delivery"]','Free shipping and delivery',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
