INSERT INTO Benefit VALUES('rewards','Earn up to 11x total miles on eligible United flights (6x as a United Club member plus 5x from the card), 5x miles on other eligible United purchases, 5x on prepaid hotels through Renowned Hotels & Resorts, 2x on other travel and dining (including delivery), and 1x on everything else.',NULL,'60383eae-3eb3-4f13-9855-6422d2cd8038','c5635f5d-cc5f-4b40-8636-d533a243197d',NULL,'Up to 11x on United flights, 5x United purchases/hotels, 2x travel and dining, 1x other.','["miles","earning","united","11x flights","2x dining"]','Earning rates','Up to 11x United',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('lounge','Includes a United Club membership for access to United Club lounges and participating partner lounges when flying United, plus two free checked bags and Premier Access priority check-in and boarding.',NULL,'c2b21953-84d9-4293-b209-6a9819c86a77','c5635f5d-cc5f-4b40-8636-d533a243197d',NULL,'United Club lounge access, two free checked bags, and Premier Access.','["united","lounge","checked bags","premier access","airline"]','United Club access and bags','2 free checked bags',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('rewards','Earn 3x miles on Delta purchases made directly with Delta and 1x miles on all other eligible purchases. Also get 20% back on eligible in-flight purchases and 10% back on qualifying concessions purchases (up to $250 per calendar year).',NULL,'cc9bfddf-bef7-4e7f-a0db-49c4b1c43e61','78f6f952-c51d-47d4-8a82-6668fe5b7726',NULL,'3x miles on Delta purchases, 1x on everything else, plus 20% back in-flight.','["miles","earning","delta","3x delta","inflight"]','Earning rates','3x Delta',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('lounge','Includes Delta Sky Club access (subject to visit limits for some cardholders) and Centurion Lounge access when flying Delta, plus a companion certificate each year after renewal and status boosts toward Medallion status.',NULL,'1b877467-7fcd-4f2b-97bd-79b09cec5bf4','78f6f952-c51d-47d4-8a82-6668fe5b7726',NULL,'Sky Club access, an annual companion certificate, and status boosts.','["delta","lounge","companion certificate","status","airline"]','Sky Club access and companion certificate',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('rewards','Earn 4x miles on eligible American Airlines purchases (5x total after $150,000 in calendar-year spend), 12x miles on eligible AAdvantage Hotels and AAdvantage Cars bookings, and 1x miles on all other purchases.',NULL,'26b0d3d4-01d0-4f9d-aac9-a11cfa7f100e','41d0b9d4-992c-4bc2-bb97-cbbb25ae33fb',NULL,'4x American Airlines (5x after $150k/yr), 12x AAdvantage Hotels/Cars, 1x other.','["miles","earning","american airlines","4x","12x hotels"]','Earning rates','4x American Airlines',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('lounge','Includes an Admirals Club membership for access to American Airlines Admirals Club lounges, plus a free checked bag and priority boarding on eligible American Airlines flights.',NULL,'db6dbd9c-1f1d-4fc9-a436-c1bfd3526db1','41d0b9d4-992c-4bc2-bb97-cbbb25ae33fb',NULL,'Admirals Club membership, a free checked bag, and priority boarding.','["american airlines","admirals club","lounge","checked bag","priority boarding"]','Admirals Club access and bags',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('rewards','Earn 3x miles on Alaska Airlines and Hawaiian Airlines purchases and 2x miles on eligible gas, EV charging, cable, streaming, and local transit (including rideshare), with 1x on all other purchases. Also get 20% back on eligible in-flight purchases.',NULL,'0e3705a1-8ef6-4c79-8f20-dd45b074af93','49d642c7-9911-48c7-b009-17815865cf39',NULL,'3x Alaska/Hawaiian, 2x gas/EV/streaming/transit, 1x other, plus 20% back in-flight.','["miles","earning","alaska airlines","3x","2x gas"]','Earning rates','3x Alaska',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','Includes an annual companion fare from $99 (plus taxes and fees), a free checked bag for you and up to six guests on the same reservation, and priority boarding.',NULL,'fb494f30-d520-4192-9e56-6603f4b0d038','49d642c7-9911-48c7-b009-17815865cf39',NULL,'Annual companion fare from $99, a free checked bag, and priority boarding.','["alaska airlines","companion fare","checked bag","priority boarding","airline"]','Companion fare and free checked bag',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('streaming','Higher-tier T-Mobile plans bundle streaming services (such as Netflix, Apple TV+, or Hulu depending on the plan), include international data and texting, and offer in-flight Wi-Fi on eligible flights.',NULL,'af6d4797-a834-4236-9e89-5c57bef93760','380b7921-8bd8-4e40-bfe9-d1848d3df32e',NULL,'Bundled streaming, international data, and in-flight Wi-Fi depending on the plan.','["t-mobile","cellular","streaming","netflix","international data","wifi"]','Streaming and international perks',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('streaming','Verizon''s higher-tier plans offer discounted or included bundles (such as Disney+, Hulu, Netflix, or Apple One), plus hotspot data and international perks depending on the plan.',NULL,'0e5b66c8-2060-4652-8be1-c7565d28cf33','f0fdb599-de1d-4d9f-98c8-8fd11970e73d',NULL,'Discounted streaming bundles plus hotspot and international perks depending on the plan.','["verizon","cellular","streaming","disney plus","netflix","hotspot"]','Streaming bundles and hotspot data',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('streaming','AT&T''s higher-tier plans include hotspot data, international roaming perks, and device offers, with some plans bundling streaming services such as Max.',NULL,'d6f75a9b-707f-49f5-8ed7-86b3c12cb952','6139789e-930a-413f-a0f8-dda28403e82d',NULL,'Hotspot data, international perks, and device/streaming offers depending on the plan.','["att","cellular","streaming","hotspot","international"]','Hotspot and international perks',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','Lyra provides evidence-based mental health care through an employer or health plan: therapy, coaching, psychiatry, and medication management, with appointments typically available in days rather than weeks. It also offers self-guided digital programs.',NULL,'41966d46-2638-4370-b9d7-a21bb6699e61','97a10093-c2e4-4e1b-a93c-efd4e1650257',NULL,'Therapy, coaching, psychiatry, and medication management with fast appointments, via your employer or health plan.','["mental health","therapy","coaching","psychiatry","eap","employer"]','Therapy, coaching, and psychiatry',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','Lyra is designed for the whole family, including children and teens (with thousands of children''s mental health specialists) and couples. Access and cost depend on what your employer or plan has arranged.',NULL,'5e2546bc-8434-4c35-8348-a9a8d05d5c50','97a10093-c2e4-4e1b-a93c-efd4e1650257',NULL,'Whole-family mental health support, including children, teens, and couples.','["family","children","teens","couples","counseling"]','Family and couples support',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','Spring Health offers personalized mental health care through employers or insurance: therapy, coaching, medication management, and self-guided tools. A digital assessment matches you to a care plan, and sessions can be as low as $0 depending on your coverage.',NULL,'7270d03c-307e-4d42-88d3-1ed2f38e0fdb','b35b69b5-d5c9-4630-a80c-9d2d7b88bc6f',NULL,'Therapy, coaching, and medication support matched by assessment, sometimes as low as $0 per session.','["mental health","therapy","coaching","medication","eap","employer"]','Personalized therapy and coaching',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','Also includes crisis support, specialty programs, and family care, with in-network clinicians you can filter by specialty, language, and availability. Access depends on your employer or health plan.',NULL,'143e33be-d43a-4dfd-80ba-6ad2a7de2d2e','b35b69b5-d5c9-4630-a80c-9d2d7b88bc6f',NULL,'Crisis support and specialty/family care, depending on your employer or plan.','["crisis support","specialty care","family","employer","insurance"]','Crisis and specialty support',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','One Care.com membership covers child care, senior care, pet care, and housekeeping. You can search local caregivers, view profiles and reviews, and message them in-app. Some employers provide Care.com as a backup-care benefit.',NULL,'49a0248a-9faa-4b56-861e-777bb28a8961','a47f32d8-7132-48bb-928d-0baf8149bb50',NULL,'One membership to find child, senior, pet, and home caregivers in your area.','["child care","senior care","pet care","housekeeping","caregivers","employer"]','Child, senior, and pet care',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','Premium features include background check requests, detailed caregiver profiles, and the ability to post a job and receive applicants. Employer-sponsored backup care may be free or subsidized.',NULL,'e99e1f91-76bc-438e-a3d3-5062b3b58baa','a47f32d8-7132-48bb-928d-0baf8149bb50',NULL,'Background checks, caregiver profiles, and job posting; sometimes employer-subsidized.','["background check","backup care","employer","family"]','Screening and backup care',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','AARP membership includes discounts on hotels, car rentals, restaurants, and entertainment, plus access to travel resources and insurance offers. Many discounts are available regardless of age.',NULL,'52c44bfd-adce-4e36-ac7a-4192ac82b5ad','8c2e8398-e9bc-4fad-ba62-d7ba16ba3915',NULL,'Discounts on hotels, rental cars, dining, and entertainment, plus insurance offers.','["aarp","discount","hotel","rental car","dining","travel"]','Member discounts',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('shopping','REI Co-op membership is a one-time fee that pays an annual member dividend (typically 10% back on eligible full-price purchases), plus access to gear rentals, used gear, shop-service discounts, and member events.',NULL,'64e83931-f746-4f50-b93d-e63597cd8f27','cedef2ce-2b54-423f-b4a7-fd0efae25c29',NULL,'One-time membership with an annual dividend, gear rentals, and shop-service discounts.','["rei","outdoors","dividend","gear rental","used gear"]','Member dividend and gear rentals','One-time $30',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','A free library card often includes free digital access to newspapers like the New York Times, ebooks and audiobooks via Libby, streaming services like Kanopy, research databases, and discounted or free museum passes.',NULL,'824634f6-6900-44d3-bee3-442fef858c54','0ecac656-a47b-4e51-9ec8-af3490fac439',NULL,'Free NYT access, ebooks/audiobooks, streaming, databases, and museum passes.','["library","nytimes","ebooks","libby","kanopy","museum passes"]','Digital access and museum passes',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','A museum membership usually includes free admission for a year, reciprocal admission to other participating museums, previews of new exhibits, member events, and discounts at the shop, cafe, and parking. Benefits vary by museum and tier.',NULL,'a36e4df7-efd6-467d-a77e-0317b0ed8c1b','be788e13-2714-46af-83da-dc1359661d5e',NULL,'Free year of admission plus reciprocal museum access, previews, events, and shop discounts.','["museum","reciprocal","admission","events","culture"]','Admission and reciprocal access',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','A zoo or aquarium membership typically includes a year of free admission, free or discounted parking, guest passes, and discounts on events and food. Many offer reciprocal admission at other zoos and aquariums.',NULL,'f73ed1f8-9f10-4c0c-883a-9276040c8275','dd0ea7ed-414f-47c1-9868-3e884be548d8',NULL,'A year of free admission plus parking, guest passes, and reciprocal zoo access.','["zoo","aquarium","admission","parking","guest passes","family"]','Admission and reciprocal access',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('rewards','Earn 5% cash back on up to $1,500 in combined purchases in rotating quarterly categories you activate, 5% on travel purchased through Chase Travel, 3% on dining and drugstore purchases, and 1% on everything else.',NULL,'df2fa167-7169-4ee8-aac8-c35d25c7551a','707c0892-8b5b-49f9-a798-6426508b91e7',NULL,'5% rotating quarterly categories (activate, $1,500 cap), 5% Chase Travel, 3% dining and drugstores, 1% other.','["cash back","earning","5% rotating","3% dining","no annual fee"]','Earning rates','5% rotating categories',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('shopping','Includes purchase protection against damage or theft for 120 days, extended warranty coverage, and trip cancellation and interruption insurance on eligible purchases.',NULL,'7dcd2963-922e-40e8-9cf4-b790f3c8a96c','707c0892-8b5b-49f9-a798-6426508b91e7',NULL,'Purchase protection, extended warranty, and trip cancellation coverage.','["purchase protection","warranty","trip cancellation","shopping"]','Purchase and travel protections',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
