INSERT INTO Benefit VALUES('rewards','Earn 3x points on travel, shipping purchases, internet, cable and phone services, and advertising purchases with social media and search engines (up to $150,000 combined each account anniversary year), and 1x on everything else.',NULL,'24e90c42-846b-448f-a3ab-ecb9c2b58baf','43fcdb1d-8c7a-4594-80ff-74c0d3daff89',NULL,'3x travel, shipping, internet/cable/phone, and advertising (up to $150k/yr), 1x other.','["points","earning","3x travel","3x advertising","business"]','Earning rates','3x bonus categories',NULL,NULL,1789743511,NULL,'seed','verified','seed');
