INSERT INTO Benefit VALUES('rewards','Earn an unlimited 1.5% cash back on every purchase, with no categories to track and no annual fee.',NULL,'28477fcf-a06a-4295-8f02-dac453be01d0','979ae2c8-4239-471a-92c0-5d05a3921f9f',NULL,'Unlimited 1.5% cash back on all purchases.','["cash back","earning","1.5%","flat rate","business"]','Earning rates','1.5% back',NULL,NULL,1789743511,NULL,'seed','verified','seed');
