INSERT INTO Benefit VALUES('travel','Includes a free checked bag for you and one companion on United flights, priority boarding, two United Club one-time passes each year, and a Global Entry, TSA PreCheck, or NEXUS application fee credit.',NULL,'f4b1b8c9-4fd0-43f9-9a0d-7fe4f2b73acd','8a2e9ccb-2eb1-4e54-84b6-5928bb411d20',NULL,'Free checked bag, priority boarding, two United Club passes, and a Global Entry/TSA credit.','["united","checked bag","priority boarding","united club","global entry"]','Airline perks',NULL,NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','Includes a free night award each account anniversary valid at Category 1-4 World of Hyatt hotels, and 5 tier-qualifying night credits each year plus 2 more for every $5,000 spent on the card.',NULL,'a6f35d3d-a574-483c-858a-e71308d6a743','f9b378d1-abcb-4b37-a7ef-a33d1d2ace0a',NULL,'Annual Category 1-4 free night plus tier-qualifying night credits toward status.','["hyatt","free night","hotel","elite nights","status"]','Annual free night and elite nights','1 free night/year',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('rewards','Earn 4x points at Hyatt hotels, 2x points on restaurants, airline tickets purchased directly with the airline, local transit, and fitness clubs, and 1x on all other purchases.',NULL,'5479014b-3070-42db-98cd-678e7d36f51e','f9b378d1-abcb-4b37-a7ef-a33d1d2ace0a',NULL,'4x Hyatt, 2x dining, airfare, transit, and fitness; 1x other.','["points","earning","4x hyatt","2x dining","hotel"]','Earning rates','4x Hyatt',NULL,NULL,1789743511,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','Includes a free night award each account anniversary valid at hotels up to 35,000 points, 15 elite night credits toward Marriott Bonvoy status each year, and complimentary Silver Elite status.',NULL,'e24042d4-3baa-477c-b1e9-406384b76d96','471a3f7b-dfc6-4aaf-bc2b-fa6858304326',NULL,'Annual free night (up to 35k points), 15 elite night credits, and Silver Elite status.','["marriott","free night","hotel","elite nights","silver elite"]','Annual free night and elite nights','1 free night/year',NULL,NULL,1789743511,NULL,'seed','verified','seed');
