INSERT INTO Benefit VALUES('travel','Includes a free night award each account anniversary, a fourth night free on award stays, and complimentary IHG One Rewards Platinum Elite status with room upgrades and bonus points.',NULL,'24b05002-90f0-4b11-bfb6-995a85e98e8f','25f8d8a1-9137-49f7-9e14-c31eabe88b1e',NULL,'Annual free night, fourth night free on awards, and Platinum Elite status.','["ihg","free night","hotel","fourth night free","platinum elite"]','Annual free night and elite status','1 free night/year',NULL,NULL,1789743511,NULL,'seed','verified','seed');
